export function formatMinor(amountMinor, currency) {
  if (!Number.isSafeInteger(amountMinor) || typeof currency !== "string" || !/^[A-Z]{3}$/.test(currency)) throw new TypeError("formatMinor(amountMinor, currency)");
  const sign = amountMinor < 0 ? "-" : "";
  const absolute = Math.abs(amountMinor);
  return `${currency} ${sign}${Math.floor(absolute / 100)}.${String(absolute % 100).padStart(2, "0")}`;
}

