import { formatMinor } from "./money.mjs";

export function totalLine(items) {
  const currency = items.length ? items[0].currency : "USD";
  const total = items.reduce((sum, item) => sum + item.amountMinor, 0);
  return `Total (${items.length} items): ${formatMinor(total, currency)}`;
}
